package org.diy.liferecorder;

import android.content.*;
import android.net.Uri;
import org.json.*;
import java.io.*;
import java.nio.*;
import java.util.*;

/** Synthetic-only regression checks for search freshness, evidence validation and memory policy. */
final class SearchMemoryTests {
    private static int checks;
    private interface Action { void run()throws Exception; }
    private static void check(boolean value,String reason)throws Exception{if(!value)throw new IOException(reason);checks++;}
    private static void rejects(Action action,String reason)throws Exception{boolean rejected=false;try{action.run();}catch(IOException expected){rejected=true;}check(rejected,reason);}
    private static JSONObject segment(String text,long start,long end)throws Exception{return new JSONObject().put("start_ms",start).put("end_ms",end).put("speaker","说话人 1").put("text",text);}
    private static void speech(RecordStore db,String id,String text)throws Exception{db.editSpeech(id,db.audio(id).optLong("transcript_revision"),new JSONObject().put("text",text).put("segments",new JSONArray().put(segment(text,100,900))));}
    private static JSONObject input(RecordStore db,String source,String question)throws Exception{String job=db.addJob("","answer",new JSONObject().put("sources",new JSONArray().put(source)).put("question",question).put("provider",new JSONObject().put("model","synthetic")).put("citation_request",true));return new JSONObject(db.rows("SELECT input FROM jobs WHERE id=?",job).getJSONObject(0).getString("input"));}
    static int run(Context context)throws Exception {
        checks=0;SharedPreferences policy=context.getSharedPreferences("understanding",0);boolean hadPolicy=policy.contains("memory_enabled"),oldPolicy=policy.getBoolean("memory_enabled",true);List<String> sources=new ArrayList<>();File wave=new File(context.getCacheDir(),"search-memory-synthetic.wav");
        ByteBuffer bytes=ByteBuffer.allocate(32044).order(ByteOrder.LITTLE_ENDIAN);bytes.put(new byte[]{82,73,70,70}).putInt(32036).put(new byte[]{87,65,86,69,102,109,116,32}).putInt(16).putShort((short)1).putShort((short)1).putInt(16000).putInt(32000).putShort((short)2).putShort((short)16).put(new byte[]{100,97,116,97}).putInt(32000);try(FileOutputStream out=new FileOutputStream(wave)){out.write(bytes.array());}
        try(RecordStore db=new RecordStore(context);RecordSearch index=new RecordSearch(context)){
            policy.edit().putBoolean("memory_enabled",true).commit();String first=db.importUri(Uri.fromFile(wave)),second=db.importUri(Uri.fromFile(wave));sources.add(first);sources.add(second);long now=System.currentTimeMillis(),older=now-8L*86400000;
            db.update("audio",first,"title","合成标题琥珀岛");db.update("audio",second,"title","合成标题青松岛");db.getWritableDatabase().execSQL("UPDATE audio SET created=? WHERE id=?",new Object[]{now,first});db.getWritableDatabase().execSQL("UPDATE audio SET created=? WHERE id=?",new Object[]{older,second});speech(db,first,"最后拍板使用蓝色版本，Project Cedar 将在周五提交。");speech(db,second,"旅行讨论决定去森林。");
            final int[] completed={0};index.sync(db,(done,total)->completed[0]=done);check(completed[0]>=2,"index reports completed source work");RecordSearch.Result exact=index.find("蓝色版本",0,Long.MAX_VALUE);check(exact.total>0&&exact.hits.get(0).source.equals(first)&&exact.hits.get(0).start==100&&exact.hits.get(0).timed,"Chinese phrase search returns exact original utterance offset");
            check(index.find("project cedar",0,Long.MAX_VALUE).hits.stream().anyMatch(h->h.source.equals(first)),"Latin search is case insensitive");check(index.find("方案最后定了什么",0,Long.MAX_VALUE).hits.stream().anyMatch(h->h.source.equals(first)),"descriptive query expands known decision expressions locally");check(index.find("森林",now-86400000,Long.MAX_VALUE).total==0,"date range excludes older utterances");check(index.find("森林",older-1,older+1).total>0,"inclusive start and exclusive end cover requested source date");check(index.find("zzznomatchqwerty",0,Long.MAX_VALUE).total==0,"empty retrieval never falls back to unrelated recent records");check(index.find("\" OR *",0,Long.MAX_VALUE).total==0,"FTS operators in user text cannot expand to all records");
            db.update("audio",first,"title","合成标题紫藤岛");index.sync(db,null);check(index.find("琥珀岛",0,Long.MAX_VALUE).total==0&&index.find("紫藤岛",0,Long.MAX_VALUE).total>0,"title change removes stale indexed title");speech(db,first,"明天去陶艺工坊，Project Maple 的预算是三百元。");index.sync(db,null);check(index.find("蓝色版本",0,Long.MAX_VALUE).total==0&&index.find("陶艺工坊",0,Long.MAX_VALUE).total>0,"transcript revision replaces all previous indexed passages");
            db.addCandidate("facts",first,"我的猫叫糖霜。");String memory=db.rows("SELECT id FROM facts WHERE source=? ORDER BY created DESC LIMIT 1",first).getJSONObject(0).getString("id");index.sync(db,null);check(index.find("糖霜",0,Long.MAX_VALUE).total==0,"pending memories never enter search results");db.update("facts",memory,"state","accepted");index.sync(db,null);check(index.find("糖霜",0,Long.MAX_VALUE).hits.stream().anyMatch(h->h.kind.equals("memory")),"only confirmed memory is searchable");db.update("facts",memory,"text","我的猫叫砂糖。");index.sync(db,null);check(index.find("糖霜",0,Long.MAX_VALUE).total==0&&index.find("砂糖",0,Long.MAX_VALUE).total>0,"memory correction removes stale wording from local index");
            JSONObject enabled=input(db,first,"预算是多少？");SourceAnswer.checkEvidence(db,enabled);JSONArray units=enabled.getJSONArray("citation_units");check(units.length()==1&&units.getJSONObject(0).getLong("source_revision")==db.audio(first).getLong("transcript_revision"),"question freezes playable utterances with source revision");check(enabled.getJSONArray("evidence_snapshot").getJSONObject(0).getJSONArray("accepted_memories").length()==1,"enabled question includes confirmed memory snapshot");
            JSONObject citation=new JSONObject().put("unit_id",units.getJSONObject(0).getString("unit_id")).put("quote","预算是三百元"),claim=new JSONObject().put("kind","observed").put("text","预算是三百元。").put("citations",new JSONArray().put(citation));JSONObject answer=SourceAnswer.validate(new JSONObject().put("claims",new JSONArray().put(claim)).put("unanswered",""),units);JSONObject savedRef=answer.getJSONArray("claims").getJSONObject(0).getJSONArray("citations").getJSONObject(0);check(savedRef.getString("source_id").equals(first)&&savedRef.getLong("start_ms")==100&&savedRef.getLong("end_ms")==900,"validated citations derive source and playback offsets from evidence, never model timestamps");
            JSONObject badQuote=new JSONObject(claim.toString());badQuote.getJSONArray("citations").getJSONObject(0).put("quote","预算是九百元");rejects(()->SourceAnswer.validate(new JSONObject().put("claims",new JSONArray().put(badQuote)),units),"invented quote cannot be persisted as an answer");JSONObject badSource=new JSONObject(claim.toString());badSource.getJSONArray("citations").getJSONObject(0).put("unit_id","unknown:0");rejects(()->SourceAnswer.validate(new JSONObject().put("claims",new JSONArray().put(badSource)),units),"citation must belong to explicitly selected source evidence");JSONObject noCitation=new JSONObject(claim.toString()).put("citations",new JSONArray());rejects(()->SourceAnswer.validate(new JSONObject().put("claims",new JSONArray().put(noCitation)),units),"claim without a source is rejected");check(!SourceAnswer.validate(new JSONObject().put("claims",new JSONArray()),units).getString("unanswered").isEmpty(),"no-evidence answer explicitly describes insufficient records");
            db.update("facts",memory,"state","inactive");rejects(()->SourceAnswer.checkEvidence(db,enabled),"queued answer is invalid after a used memory is deactivated");index.sync(db,null);check(index.find("砂糖",0,Long.MAX_VALUE).total==0,"inactive memory leaves local search");db.update("facts",memory,"state","accepted");JSONObject fresh=input(db,first,"预算是多少？");JSONObject analysisSnapshot=AnalysisPipeline.snapshot(db,new JSONArray().put(first));JSONObject oldContext=LifeMemory.context(db,analysisSnapshot);JSONObject oldReview=LifeReview.snapshot(db,now-86400000,now+86400000);
            policy.edit().putBoolean("memory_enabled",false).commit();rejects(()->SourceAnswer.checkEvidence(db,fresh),"global memory switch invalidates already queued answer snapshots before request");rejects(()->LifeMemory.checkContext(db,oldContext),"global memory switch invalidates analysis context");rejects(()->LifeReview.checkCurrent(db,oldReview),"global memory switch invalidates review snapshot before request");check(LifeMemory.policyChanged(db,new JSONObject().put("memory_context",oldContext))&&LifeMemory.policyChanged(db,new JSONObject().put("review_snapshot",oldReview)),"each provider request observes policy changes through cancellation guard");check(LifeMemory.context(db,analysisSnapshot).getJSONArray("confirmed_memories").length()==0,"disabled analysis omits confirmed memories");check(LifeReview.snapshot(db,now-86400000,now+86400000).getJSONArray("accepted_memories").length()==0,"disabled review omits confirmed memories");JSONObject disabled=input(db,first,"预算是多少？");SourceAnswer.checkEvidence(db,disabled);check(!disabled.getBoolean("memory_enabled")&&disabled.getJSONArray("evidence_snapshot").getJSONObject(0).getJSONArray("accepted_memories").length()==0,"new questions remain usable with memory disabled and no memory payload");check(db.rows("SELECT id FROM facts WHERE id=? AND state='accepted'",memory).length()==1,"switching memory off preserves saved facts");
            speech(db,first,"新修订的说法，预算是四百元。");rejects(()->SourceAnswer.checkEvidence(db,disabled),"transcript edits invalidate queued question evidence");JSONObject trimmed=db.audio(first);trimmed.put("source_retained",0).put("vad_map",new JSONObject().put("ranges",new JSONArray().put(new JSONObject().put("source_start_sample",8000).put("source_end_sample",16000))).toString());check(!SourceAnswer.playable(trimmed,units.getJSONObject(0)),"citations in discarded source audio cannot claim a playable jump");db.update("audio",first,"transcript","没有时间码的人工文字。");rejects(()->SourceAnswer.prepare(db,new JSONObject().put("sources",new JSONArray().put(first))),"untimed text is searchable but cannot create unverifiable playback citations");
            index.sync(db,null);db.forget(second);sources.remove(second);check(index.find("森林",0,Long.MAX_VALUE).total==0,"deleting source immediately removes its derived index without waiting for another sync");
        }finally{try(RecordStore db=new RecordStore(context)){for(String source:sources)try{db.forget(source);}catch(Exception ignored){}}wave.delete();SharedPreferences.Editor edit=policy.edit();if(hadPolicy)edit.putBoolean("memory_enabled",oldPolicy);else edit.remove("memory_enabled");edit.commit();}
        return checks;
    }
}
